/// Business-hook errors propagate; any hook side effects are not rolled back.
/// Result conversion errors propagate; response serialization failures become codec errors.
/// # Algorithm
/// Check the protocol method and consume typed parameters. Convert typed wire parameters with `decode_delete_files_params`.
/// Await [`ILanguageServer::will_delete_files`] once; do not retry on failure.
/// Encode the result using `encode_workspace_edit`.
/// Preserve absence; a failed conversion inside `Some` is an error, not absence.
/// Build a success response with the original ID; the runtime sends it later.
/// # Flow
/// ```text
///  [consume request parameters]
///               |
///        <decode succeeds?>
///          /          \
///        no           yes
///         |            |
///  [InvalidParams/Err] [business hook]
///                      |
///               <hook + encoding succeed?>
///                 /              \
///               no               yes
///                |                |
///              [Err]       [response, same ID]
/// ```
/// # Examples
/// Private dispatcher context; `wire_params` has the marker's associated parameter type.
/// ```text
/// let envelope = crate::rpc::Request::new::<lsp_types::request::WillDeleteFiles>(id.clone(), wire_params)?;
/// let response = will_delete_files(&server, context, envelope).await?;
/// assert_eq!(response.id, Some(id));
/// ```
pub(in crate::server::wrapper) async fn will_delete_files<S: ILanguageServer>(
    server: &S,
    context: Context,
    mut request: Request,
) -> ServerResult<Response> {
    let params = request
        .take_params::<lsp_types::request::WillDeleteFiles>()
        .map_err(invalid_params)?;
    let params = decode_delete_files_params(params)?;
    let result = server.will_delete_files(context, params).await?;
    let result = (result).map(encode_workspace_edit).transpose()?;
    Response::success::<lsp_types::request::WillDeleteFiles>(request.id, result)
        .map_err(codec_error)
}
